function workFacts(work){
 if(!work)return '';
 return '<div class="work-facts" aria-label="'+t('Work summary','工作摘要')+'"><div><strong>'+work.active+'</strong><span>'+t('in progress','進行中')+'</span></div><div><strong>'+work.accepted+'</strong><span>'+t('accepted results','已驗收成果')+'</span></div><div><strong>'+work.recorded_operations+'</strong><span>'+t('recorded operations','筆執行紀錄')+'</span></div>'+(work.unavailable?'<p class="small">'+work.unavailable+' '+t('task records need reconnecting','筆任務無法確認最新狀態')+'</p>':'')+'</div>';
}
function recentActivity(work){
 if(!work?.activity.length)return '<p class="quiet-empty">'+t('Activity appears here as work is assigned, delivered and reviewed. No usage report is needed.','任務安排、交付與審查會出現在這裡，不必等模型用量回報。')+'</p>';
 const seen=new Set(),recent=work.activity.filter(event=>{if(seen.has(event.task_key))return false;seen.add(event.task_key);return true;}).slice(0,4);
 return '<ol class="work-feed">'+recent.map(event=>{
  const title=event.kind==='lifecycle'?lifecycleAction(event.action):activityLabel(event.action)+' · '+operationState(event.state);
  const actor=event.actor?.agent_id,model=event.model||event.requested_model;
  return '<li><span class="feed-dot '+(event.action==='close'?'accepted':'')+'" aria-hidden="true"></span><div><div class="feed-label"><strong>'+escape(title)+'</strong><time>'+escape(date(event.at))+'</time></div>'+(event.task_id?'<a href="'+link('task',event.project_id,event.task_id)+'">'+escape(event.title)+'</a>':'<p>'+escape(event.title)+'</p>')+'<p class="small">'+escape([actor,model&&(event.model?model:t('Requested: ','已指定：')+model)].filter(Boolean).join(' · '))+'</p>'+(event.summary?'<details><summary>'+t('What changed','查看內容')+'</summary><p>'+escape(event.summary)+'</p></details>':'')+'</div></li>';
 }).join('')+'</ol>';
}
function outcomeCards(work){
 if(!work?.outcomes.length)return '<p class="quiet-empty">'+t('The first delivered result will appear here, together with its review.','第一份成果交付後，會連同審查結果顯示在這裡。')+'</p>';
 return '<div class="outcome-cards">'+work.outcomes.slice(0,2).map(result=>'<article><div class="feed-label"><span class="badge '+(result.accepted?'accepted':'')+'">'+(result.accepted?t('Accepted','已驗收'):result.task_state==='cancelled'?t('Cancelled','已取消'):result.review_judgment==='fail'?t('Needs repair','需要修正'):t('Awaiting acceptance','等待驗收'))+'</span><time>'+escape(date(result.at))+'</time></div><h3><a href="'+link('task',result.project_id,result.task_id)+'">'+escape(result.title)+'</a></h3>'+(result.summary?'<p class="result-excerpt">'+escape(result.summary)+'</p>':'')+'<a class="result-link" href="'+link('task',result.project_id,result.task_id)+'">'+t('Read the result & review','查看成果與審查')+' →</a></article>').join('')+'</div>';
}
function projectPulse(project){
 const work=project.work,active=snapshot.tasks.filter(task=>task.project_id===project.id&&task.read_status==='available'&&!['done','cancelled'].includes(task.task_state));
 const focus=active[0];
 return workFacts(work)+'<div class="project-pulse"><span class="eyebrow">'+t('Right now','目前進度')+'</span><h2>'+(focus?'<a href="'+link('task',project.id,focus.id)+'">'+escape(focus.title)+'</a>':project.complete?t('No unfinished tasks','目前的任務都已告一段落'):t('Some work cannot be confirmed','部分工作狀態尚無法確認'))+'</h2><p>'+escape(focus?taskNext(focus):project.complete?t('Review the delivered results below or start a new task with your agent.','可以查看下方已交付成果，或向 Agent 交辦下一項任務。'):t('Reconnect to confirm the current task state.','重新連線後才能確認目前工作狀態。'))+'</p><div class="pulse-meta">'+(focus?'<span>'+escape(focus.actor?.agent_id||t('Assigned executor','已安排執行'))+'</span><span>'+t('Updated ','更新於 ')+escape(date(focus.updated_at))+'</span>':'')+'<a href="'+link('autonomy',project.id)+'">'+t('Autonomous improvement: ','自主改善：')+escape(autonomyLabel(project.autonomy))+' →</a></div></div>'+
 '<div class="project-story"><section><div class="section-heading"><h2>'+t('Recent activity','近期動態')+'</h2><span class="small">'+t('From task and execution records','來自任務與執行紀錄')+'</span></div>'+recentActivity(work)+'</section><section><div class="section-heading"><h2>'+t('Delivered results','已交付的成果')+'</h2></div>'+outcomeCards(work)+'</section></div>';
}
