  if(target.dataset.page){page+=Number(target.dataset.page);saveListState();render();const list=document.querySelector('.work-toolbar')||$('content');list.scrollIntoView({block:'start'});const first=document.querySelector('.task-row a,.project-row a');(first||$('content')).focus({preventScroll:true});}
  if(target.id==='clear-task-filters'){query='';filter='all';page=0;goalPage=0;$('search').value='';saveListState();render();$('search').focus();}
